// Thai Travel Passport — accounts + per-user passport storage on D1.
// Serves the page (embedded below) and handles /api/*.

const COOKIE = "tp_session";
const SESSION_DAYS = 60;
const PBKDF2_ITER = 100000;
const MAX_DATA = 64 * 1024;
const enc = new TextEncoder();

let schemaReady = null;
function ensureSchema(env) {
  if (!schemaReady) {
    schemaReady = env.DB.batch([
      env.DB.prepare(`CREATE TABLE IF NOT EXISTS users (
        id TEXT PRIMARY KEY, email TEXT NOT NULL UNIQUE, name TEXT NOT NULL DEFAULT '',
        pw TEXT NOT NULL, salt TEXT NOT NULL, created INTEGER NOT NULL)`),
      env.DB.prepare(`CREATE TABLE IF NOT EXISTS sessions (
        token TEXT PRIMARY KEY, user_id TEXT NOT NULL, expires INTEGER NOT NULL)`),
      env.DB.prepare(`CREATE INDEX IF NOT EXISTS sessions_user ON sessions(user_id)`),
      env.DB.prepare(`CREATE TABLE IF NOT EXISTS passports (
        user_id TEXT PRIMARY KEY, data TEXT NOT NULL, updated INTEGER NOT NULL)`),
      env.DB.prepare(`CREATE TABLE IF NOT EXISTS attempts (
        k TEXT PRIMARY KEY, n INTEGER NOT NULL, reset INTEGER NOT NULL)`),
    ]).catch((e) => { schemaReady = null; throw e; });
  }
  return schemaReady;
}

/* ---------- helpers ---------- */
const json = (body, status = 200, headers = {}) =>
  new Response(JSON.stringify(body), {
    status,
    headers: { "content-type": "application/json; charset=utf-8", "cache-control": "no-store", ...headers },
  });
const err = (status, code, message) => json({ error: code, message }, status);

const b64u = (buf) => btoa(String.fromCharCode(...new Uint8Array(buf))).replace(/\+/g, "-").replace(/\//g, "_").replace(/=+$/, "");
const hex = (buf) => [...new Uint8Array(buf)].map((b) => b.toString(16).padStart(2, "0")).join("");
const randomToken = (n = 32) => b64u(crypto.getRandomValues(new Uint8Array(n)));
const sha256 = async (s) => hex(await crypto.subtle.digest("SHA-256", enc.encode(s)));

async function hashPassword(password, saltHex) {
  const salt = saltHex ? Uint8Array.from(saltHex.match(/../g).map((h) => parseInt(h, 16))) : crypto.getRandomValues(new Uint8Array(16));
  const key = await crypto.subtle.importKey("raw", enc.encode(password), "PBKDF2", false, ["deriveBits"]);
  const bits = await crypto.subtle.deriveBits({ name: "PBKDF2", hash: "SHA-256", salt, iterations: PBKDF2_ITER }, key, 256);
  return { hash: hex(bits), salt: hex(salt) };
}
function safeEqual(a, b) {
  const x = enc.encode(a), y = enc.encode(b);
  if (x.length !== y.length) return false;
  return crypto.subtle.timingSafeEqual(x, y);
}

function readCookie(req, name) {
  const c = req.headers.get("cookie") || "";
  for (const part of c.split(/;\s*/)) {
    const i = part.indexOf("=");
    if (i > 0 && part.slice(0, i) === name) return decodeURIComponent(part.slice(i + 1));
  }
  return null;
}
const sessionCookie = (token, maxAge) =>
  `${COOKIE}=${token}; Path=/; HttpOnly; Secure; SameSite=Lax; Max-Age=${maxAge}`;

async function readJson(req) {
  if (!(req.headers.get("content-type") || "").includes("application/json")) return null;
  const text = await req.text();
  if (text.length > MAX_DATA + 4096) return null;
  try { return JSON.parse(text); } catch { return null; }
}

const normEmail = (e) => String(e || "").trim().toLowerCase();
const validEmail = (e) => /^[^\s@]{1,64}@[^\s@]{1,190}\.[^\s@]{2,}$/.test(e);

/* ---------- rate limiting (failed logins / signups) ---------- */
async function tooMany(env, key, limit, windowMs) {
  const now = Date.now();
  const row = await env.DB.prepare("SELECT n, reset FROM attempts WHERE k = ?").bind(key).first();
  if (!row || row.reset < now) return false;
  return row.n >= limit;
}
async function bump(env, key, windowMs) {
  const now = Date.now();
  await env.DB.prepare(
    `INSERT INTO attempts (k, n, reset) VALUES (?1, 1, ?2)
     ON CONFLICT(k) DO UPDATE SET n = CASE WHEN reset < ?3 THEN 1 ELSE n + 1 END,
                                  reset = CASE WHEN reset < ?3 THEN ?2 ELSE reset END`
  ).bind(key, now + windowMs, now).run();
}

/* ---------- sessions ---------- */
async function createSession(env, userId) {
  const token = randomToken();
  const expires = Date.now() + SESSION_DAYS * 864e5;
  await env.DB.prepare("INSERT INTO sessions (token, user_id, expires) VALUES (?, ?, ?)")
    .bind(await sha256(token), userId, expires).run();
  // opportunistic cleanup
  await env.DB.prepare("DELETE FROM sessions WHERE expires < ?").bind(Date.now()).run();
  return token;
}
async function currentUser(env, req) {
  const token = readCookie(req, COOKIE);
  if (!token || token.length > 100) return null;
  const row = await env.DB.prepare(
    `SELECT u.id, u.email, u.name, s.expires FROM sessions s JOIN users u ON u.id = s.user_id WHERE s.token = ?`
  ).bind(await sha256(token)).first();
  if (!row || row.expires < Date.now()) return null;
  return { id: row.id, email: row.email, name: row.name };
}
const publicUser = (u) => ({ email: u.email, name: u.name });

async function loadPassport(env, userId) {
  const row = await env.DB.prepare("SELECT data, updated FROM passports WHERE user_id = ?").bind(userId).first();
  if (!row) return { data: null, updated: 0 };
  try { return { data: JSON.parse(row.data), updated: row.updated }; } catch { return { data: null, updated: 0 }; }
}

function cleanPassport(d) {
  if (!d || typeof d !== "object" || typeof d.visits !== "object" || d.visits === null) return null;
  const visits = {};
  let count = 0;
  for (const [k, v] of Object.entries(d.visits)) {
    if (++count > 100) break;
    if (typeof k !== "string" || k.length > 60 || !v || typeof v !== "object") continue;
    const l = Number(v.l) | 0;
    if (l < 1 || l > 3) continue;
    visits[k] = { l, d: String(v.d || "").slice(0, 10), n: String(v.n || "").slice(0, 400) };
  }
  return { holder: String(d.holder || "").slice(0, 28), visits };
}

/* ---------- handlers ---------- */
async function signup(req, env, ip) {
  const body = await readJson(req);
  if (!body) return err(400, "bad_request", "ข้อมูลไม่ถูกต้อง");
  const email = normEmail(body.email), password = String(body.password || ""), name = String(body.name || "").trim().slice(0, 40);
  if (!validEmail(email)) return err(400, "bad_email", "รูปแบบอีเมลไม่ถูกต้อง");
  if (password.length < 8 || password.length > 200) return err(400, "weak_password", "รหัสผ่านต้องยาวอย่างน้อย 8 ตัวอักษร");
  if (await tooMany(env, "signup:" + ip, 20, 3600e3)) return err(429, "rate_limited", "สมัครหลายครั้งเกินไป ลองใหม่ในอีก 1 ชั่วโมง");
  await bump(env, "signup:" + ip, 3600e3);
  const exists = await env.DB.prepare("SELECT 1 FROM users WHERE email = ?").bind(email).first();
  if (exists) return err(409, "email_taken", "อีเมลนี้มีบัญชีอยู่แล้ว ลองเข้าสู่ระบบแทน");
  const { hash, salt } = await hashPassword(password);
  const id = crypto.randomUUID();
  await env.DB.prepare("INSERT INTO users (id, email, name, pw, salt, created) VALUES (?, ?, ?, ?, ?, ?)")
    .bind(id, email, name, hash, salt, Date.now()).run();
  const token = await createSession(env, id);
  return json({ user: { email, name }, data: null, updated: 0 }, 201, { "set-cookie": sessionCookie(token, SESSION_DAYS * 86400) });
}

async function login(req, env, ip) {
  const body = await readJson(req);
  if (!body) return err(400, "bad_request", "ข้อมูลไม่ถูกต้อง");
  const email = normEmail(body.email), password = String(body.password || "");
  const key = "login:" + email, ipKey = "loginip:" + ip;
  if (await tooMany(env, key, 8, 900e3) || await tooMany(env, ipKey, 40, 900e3))
    return err(429, "rate_limited", "ใส่รหัสผิดหลายครั้งเกินไป รอ 15 นาทีแล้วลองใหม่");
  const user = await env.DB.prepare("SELECT id, email, name, pw, salt FROM users WHERE email = ?").bind(email).first();
  const { hash } = await hashPassword(password, user ? user.salt : "00".repeat(16));
  if (!user || !safeEqual(hash, user.pw)) {
    await bump(env, key, 900e3); await bump(env, ipKey, 900e3);
    return err(401, "bad_credentials", "อีเมลหรือรหัสผ่านไม่ถูกต้อง");
  }
  const token = await createSession(env, user.id);
  const p = await loadPassport(env, user.id);
  return json({ user: publicUser(user), ...p }, 200, { "set-cookie": sessionCookie(token, SESSION_DAYS * 86400) });
}

async function logout(req, env) {
  const token = readCookie(req, COOKIE);
  if (token) await env.DB.prepare("DELETE FROM sessions WHERE token = ?").bind(await sha256(token)).run();
  return json({ ok: true }, 200, { "set-cookie": sessionCookie("", 0) });
}

async function me(req, env) {
  const user = await currentUser(env, req);
  if (!user) return err(401, "signed_out", "ยังไม่ได้เข้าสู่ระบบ");
  return json({ user: publicUser(user), ...(await loadPassport(env, user.id)) });
}

async function savePassport(req, env) {
  const user = await currentUser(env, req);
  if (!user) return err(401, "signed_out", "ยังไม่ได้เข้าสู่ระบบ");
  const body = await readJson(req);
  const data = body && cleanPassport(body.data);
  if (!data) return err(400, "bad_request", "ข้อมูลไม่ถูกต้อง");
  const text = JSON.stringify(data);
  if (text.length > MAX_DATA) return err(413, "too_large", "ข้อมูลใหญ่เกินไป");
  const updated = Date.now();
  await env.DB.prepare(
    `INSERT INTO passports (user_id, data, updated) VALUES (?1, ?2, ?3)
     ON CONFLICT(user_id) DO UPDATE SET data = ?2, updated = ?3`
  ).bind(user.id, text, updated).run();
  return json({ updated });
}

async function changePassword(req, env) {
  const user = await currentUser(env, req);
  if (!user) return err(401, "signed_out", "ยังไม่ได้เข้าสู่ระบบ");
  const body = await readJson(req);
  if (!body) return err(400, "bad_request", "ข้อมูลไม่ถูกต้อง");
  const row = await env.DB.prepare("SELECT pw, salt FROM users WHERE id = ?").bind(user.id).first();
  const { hash } = await hashPassword(String(body.old || ""), row.salt);
  if (!safeEqual(hash, row.pw)) return err(401, "bad_credentials", "รหัสผ่านเดิมไม่ถูกต้อง");
  const pw = String(body.new || "");
  if (pw.length < 8 || pw.length > 200) return err(400, "weak_password", "รหัสผ่านใหม่ต้องยาวอย่างน้อย 8 ตัวอักษร");
  const n = await hashPassword(pw);
  await env.DB.batch([
    env.DB.prepare("UPDATE users SET pw = ?, salt = ? WHERE id = ?").bind(n.hash, n.salt, user.id),
    env.DB.prepare("DELETE FROM sessions WHERE user_id = ?").bind(user.id),
  ]);
  const token = await createSession(env, user.id);
  return json({ ok: true }, 200, { "set-cookie": sessionCookie(token, SESSION_DAYS * 86400) });
}

export default {
  async fetch(req, env) {
    const url = new URL(req.url);
    if (!url.pathname.startsWith("/api/")) {
      if (req.method !== "GET" && req.method !== "HEAD") return new Response("Method not allowed", { status: 405 });
      if (url.pathname !== "/" && url.pathname !== "/index.html") return new Response("Not found", { status: 404 });
      return new Response(req.method === "HEAD" ? null : PAGE, {
        headers: { "content-type": "text/html; charset=utf-8", "cache-control": "no-cache", "x-content-type-options": "nosniff", "referrer-policy": "same-origin" },
      });
    }

    // Block cross-site writes (CSRF): mutating requests must come from this site.
    if (req.method !== "GET") {
      const origin = req.headers.get("origin");
      if (origin && origin !== url.origin) return err(403, "bad_origin", "ไม่อนุญาต");
    }
    try {
      await ensureSchema(env);
      const ip = req.headers.get("cf-connecting-ip") || "unknown";
      const route = req.method + " " + url.pathname;
      switch (route) {
        case "POST /api/signup": return await signup(req, env, ip);
        case "POST /api/login": return await login(req, env, ip);
        case "POST /api/logout": return await logout(req, env);
        case "GET /api/me": return await me(req, env);
        case "PUT /api/passport": return await savePassport(req, env);
        case "POST /api/password": return await changePassword(req, env);
        default: return err(404, "not_found", "ไม่พบ");
      }
    } catch (e) {
      console.error(e);
      return err(500, "server_error", "ระบบขัดข้อง ลองใหม่อีกครั้ง");
    }
  },
};

